t = exprnd(5, 200, 1);
cens = t > 10;
t(cens) = 10;
[f, x] = ecdf(t, 'Censoring', cens);
[n, c] = ecdfhist(f, x, 8);
round(n(1:3), 3)
ecdfhist(f, x, 8), hold on, fplot(@(s) exppdf(s, 5), [0 10]), hold off

x = linspace(-3, 3, 300)';
p = [exp(-x) ones(size(x)) exp(x)];
p = p./sum(p, 2);
Y = sum(rand(300, 1) > cumsum(p, 2), 2) + 1;
B = mnrfit(x, Y);
P = mnrval(B, [-2; 0; 2]);
round(P, 2)

c = [0 0; 2 0; 1 2];
X = [randn(50, 2) + c(1, :); randn(50, 2) + c(2, :); randn(50, 2) + c(3, :)];
Y = repelem((1:3)', 50);
m = fitcdiscr(X, Y);
[~, s] = resubPredict(m);
roc = rocmetrics(Y, s, [1 2 3]);
round(roc.AUC, 3)
plot(roc)
